// v3: match-page recap overlay. A recap is generated by the golazo26-recap Cron worker and served
// at /api/v1/recap?n=N — so it appears on the match page with NO rebuild. The baked page keeps any
// recap that existed at bake time; this fills an empty slot when a fresh recap exists, and drops the
// now-stale preview (the match is over). Markup matches build.mjs storyHTML exactly (mdLite escapes,
// so innerHTML is safe). Fails safe: any error leaves the baked page untouched.
import { mdLite } from '/render.mjs';
import { escHTML, commentaryRowsHTML } from '/commentary-view.mjs';
import { bartalkApiBase } from '/bartalk-view.mjs';
import { watchRowsHTML, escWA } from '/watch-view.mjs';
import { statsRowsHTML } from '/stats-view.mjs';
import { timelineHTML, keyMomentsHTML } from '/timeline-view.mjs';

// i18n: current non-English site language (site/i18n.js sets data-lang pre-paint), appended
// as a ?lang=/&lang= suffix to the DYNAMIC prose endpoints (recap / bar-talk / watch) so D1-served
// prose arrives translated with per-row English fallback. Each hydrator below re-fetches on the
// g26:lang event (fired by i18n.js after every language selection) and re-renders idempotently.
const i18nLang = () => { const l = document.documentElement.dataset.lang; return l && l !== 'en' ? l : null; };
const langQS = () => { const l = i18nLang(); return l ? `&lang=${l}` : ''; };

const slot = document.querySelector('[data-recap-slot]');
if (slot && !slot.children.length) { // empty slot = no recap baked yet for this match
  const n = slot.getAttribute('data-recap-slot');
  const API = self.__G26_API__ || 'https://golazo26-data.onwike.workers.dev';
  const loadRecap = async () => {
    try {
      const r = await fetch(`${API}/api/v1/recap?n=${encodeURIComponent(n)}${langQS()}`, { cache: 'no-cache' });
      if (!r.ok) return;
      const { body } = await r.json();
      if (!body) return;
      slot.innerHTML = `<section class="prose"><h2>Match report</h2>${mdLite(body)}</section>`;
      document.querySelector('[data-preview-slot]')?.replaceChildren(); // match is over — drop the stale preview
    } catch (e) { /* keep the baked page */ }
  };
  loadRecap();
  document.addEventListener('g26:lang', loadRecap); // re-fetch in the new language (full innerHTML replace = idempotent)
}

// v3.04.02: ESPN blow-by-blow overlay — now LIVE. Verbatim "via ESPN" commentary at /api/v1/commentary?n=N
// (poll live tail + archival backfill) fills the baked-hidden section with NO rebuild — newest-first, key
// events highlighted, every field ESCAPED (commentary-view.mjs). The score + minute already refresh live
// (app.js tick); a one-shot fetch left the blow-by-blow frozen until a manual refresh, so it now re-polls
// in lockstep while the match is unfinished and re-fetches on bfcache restore / tab refocus. Idempotent —
// re-renders only when as_of (MAX ingested_at) advances. Fails safe: any error / no data keeps it hidden.
const cmt = document.querySelector('[data-commentary]');
if (cmt) {
  const n = cmt.getAttribute('data-commentary');
  const API2 = self.__G26_API__ || 'https://golazo26-data.onwike.workers.dev';
  const list = cmt.querySelector('.cmt-list');
  const asofEl = cmt.querySelector('.cmt-asof');
  let lastAsof = null;
  const load = async () => {
    try {
      const r = await fetch(`${API2}/api/v1/commentary?n=${encodeURIComponent(n)}`, { cache: 'no-cache' });
      if (!r.ok) return;
      const d = await r.json();
      if (!d || !Array.isArray(d.commentary) || !d.commentary.length) return;
      if (d.as_of && d.as_of === lastAsof) { cmt.hidden = false; return; } // no new entries since last paint
      lastAsof = d.as_of || lastAsof;
      list.innerHTML = commentaryRowsHTML(d.commentary, escHTML);
      if (d.as_of) asofEl.textContent = `Commentary via ESPN · as of ${new Date(d.as_of).toLocaleString()}`;
      cmt.hidden = false;
      // NOTE: the old "staleness note" on the baked key-moments strip is GONE as of Phase 2 —
      // the strip now LIVE-RENDERS from the structured match-events feed (hydrator at the end of this
      // file), so it can no longer sit stale under a live score. That render supersedes the honesty
      // marker instead of band-aiding it.
    } catch (e) { /* keep the baked page (section stays hidden) */ }
  };
  load();
  // Live tail: poll while the match is unfinished (mirrors app.js's live score tick) so new entries appear
  // without a manual refresh. The FT pill — baked, or set live by app.js at full time — stops it, and the
  // whole thing is gated to the tournament window so settled / out-of-window pages never poll.
  const T0 = Date.parse('2026-06-11T00:00:00Z'), T1 = Date.parse('2026-07-20T12:00:00Z');
  const finished = () => !!document.querySelector(`[data-match="${n}"] .pill.ft`);
  if (Date.now() >= T0 && Date.now() <= T1 && !finished()) {
    const iv = setInterval(() => {
      if (finished() || Date.now() > T1) { clearInterval(iv); return; }
      load();
    }, 45000 + Math.random() * 15000);
  }
  // bfcache restore / return-to-tab: catch up immediately instead of waiting for the next poll.
  window.addEventListener('pageshow', (e) => { if (e.persisted) load(); });
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') load(); });
}

// Bar Talk episode (greenlit): the four AI models' comedic panel reacting to THIS match, served at
// /api/v1/bar-talk?n=N (transcript_md authored by the engine, with an embedded disclaimer). Fills the
// baked-hidden section with NO rebuild; mdLite escapes its input, so innerHTML is safe. Fails safe: any
// error / no episode leaves the section hidden.
const bt = document.querySelector('[data-bartalk]');
if (bt) {
  const n = bt.getAttribute('data-bartalk');
  const API3 = bartalkApiBase(); // bar_talk source (dev: golazo26-data-dev → g26-db-dev; prod: golazo26-data)
  const loadBt = async () => {
    try {
      const r = await fetch(`${API3}/api/v1/bar-talk?n=${encodeURIComponent(n)}${langQS()}`, { cache: 'no-cache' });
      if (!r.ok) return;
      const d = await r.json();
      const md = d && d.episode && d.episode.body_md;
      if (!md) return;
      bt.querySelector('.bt-ep-body').innerHTML = mdLite(md);
      bt.hidden = false;
    } catch (e) { /* keep the baked page (section stays hidden) */ }
  };
  loadBt();
  document.addEventListener('g26:lang', loadBt); // re-fetch in the new language (idempotent innerHTML replace)
}

// Bar Talk PRE-GAME episode (buildout A.4): the four models trash-talking their own pre-match predictions,
// served at /api/v1/bar-talk?n=N&phase=pregame. Same fail-safe-hidden hydrate as the post-match episode,
// shown before kickoff; mdLite escapes its input, so innerHTML is safe. No pregame episode → stays hidden.
const btPre = document.querySelector('[data-bartalk-pre]');
if (btPre) {
  const n = btPre.getAttribute('data-bartalk-pre');
  const API4 = bartalkApiBase();
  const loadBtPre = async () => {
    try {
      const r = await fetch(`${API4}/api/v1/bar-talk?n=${encodeURIComponent(n)}&phase=pregame${langQS()}`, { cache: 'no-cache' });
      if (!r.ok) return;
      const d = await r.json();
      const md = d && d.episode && d.episode.body_md;
      if (!md) return;
      btPre.querySelector('.bt-ep-body').innerHTML = mdLite(md);
      btPre.hidden = false;
    } catch (e) { /* keep the baked page (section stays hidden) */ }
  };
  loadBtPre();
  document.addEventListener('g26:lang', loadBtPre); // re-fetch in the new language (idempotent innerHTML replace)
}

// AI Watch-Along (buildout track 3): the four models' live running commentary beside the blow-by-blow,
// served at /api/v1/watch?n=N (written per-tick by the golazo26-live-banter worker; congrats → green border).
// Near-verbatim clone of the blow-by-blow loader: live-poll while the match is unfinished, as_of-idempotent,
// one last load at FT so the closing congratulation paints, bfcache/refocus catch-up, fail-safe-hidden. Uses
// bartalkApiBase() (generated content → dev mirror on dev, prod golazo26-data on prod), not the live ESPN base.
const wa = document.querySelector('[data-watchalong]');
if (wa) {
  const n = wa.getAttribute('data-watchalong');
  const API5 = bartalkApiBase();
  const list = wa.querySelector('.wa-list');
  const asofEl = wa.querySelector('.wa-asof');
  let lastAsof = null;
  const load = async () => {
    try {
      const r = await fetch(`${API5}/api/v1/watch?n=${encodeURIComponent(n)}${langQS()}`, { cache: 'no-cache' });
      if (!r.ok) return;
      const d = await r.json();
      if (!d || !Array.isArray(d.watch) || !d.watch.length) return;
      if (d.as_of && d.as_of === lastAsof) { wa.hidden = false; return; } // no new lines since last paint
      lastAsof = d.as_of || lastAsof;
      list.innerHTML = watchRowsHTML(d.watch, escWA);
      if (d.as_of) asofEl.textContent = `AI Watch-Along · as of ${new Date(d.as_of).toLocaleString()}`;
      wa.hidden = false;
    } catch (e) { /* keep the baked page (section stays hidden) */ }
  };
  load();
  // Live tail: poll while the match is unfinished (mirrors the blow-by-blow), gated to the tournament window.
  const T0 = Date.parse('2026-06-11T00:00:00Z'), T1 = Date.parse('2026-07-20T12:00:00Z');
  const finished = () => !!document.querySelector(`[data-match="${n}"] .pill.ft`);
  if (Date.now() >= T0 && Date.now() <= T1 && !finished()) {
    const iv = setInterval(() => {
      if (Date.now() > T1) { clearInterval(iv); return; }
      if (finished()) { load(); clearInterval(iv); return; } // one last load at FT so the closing congratulation paints
      load();
    }, 45000 + Math.random() * 15000);
  }
  window.addEventListener('pageshow', (e) => { if (e.persisted) load(); });
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') load(); });
  // language switch: the as_of guard would suppress a same-data repaint — reset it, then re-fetch
  // with the new ?lang= so every line re-renders (per-row English fallback server-side).
  document.addEventListener('g26:lang', () => { lastAsof = null; load(); });
}

// Match stats (Phase 2.5): home-vs-away comparison bars from ESPN's boxscore, served at
// /api/v1/match-stats?n=N (worker/poll.mjs's 2.3 upsert, golazo26-data's 2.4 endpoint — both already
// live). LIVE DATASET (stats change every poll while a match is in progress), so this re-polls in
// lockstep with the blow-by-blow/AI Watch-Along tick above rather than fetching once — same
// as_of-idempotent re-render, same bfcache/refocus catch-up (live-hydration doctrine). GRACEFUL
// EMPTY: home and/or away can be null (pre-match, or a boxscore not yet populated) — the baked
// "not yet available" line stays visible and no row renders; never a broken/NaN row. Fails safe:
// any error leaves the baked shell (empty-state showing) untouched.
const mst = document.querySelector('[data-match-stats]');
if (mst) {
  const n = mst.getAttribute('data-match-stats');
  const API6 = self.__G26_API__ || 'https://golazo26-data.onwike.workers.dev';
  const rowsEl = mst.querySelector('.mst-rows');
  const asofEl = mst.querySelector('.mst-asof');
  let lastAsof = null;
  const load = async () => {
    try {
      const r = await fetch(`${API6}/api/v1/match-stats?n=${encodeURIComponent(n)}`, { cache: 'no-cache' });
      if (!r.ok) return;
      const d = await r.json();
      if (!d || (!d.home && !d.away)) return; // stays on the baked "not yet available" empty-state
      if (d.as_of && d.as_of === lastAsof) return; // no change since last paint
      lastAsof = d.as_of || lastAsof;
      rowsEl.innerHTML = statsRowsHTML(d.home, d.away);
      mst.classList.add('has-rows'); // hides the baked empty-state now that real rows are painted
      if (d.as_of) asofEl.textContent = `Stats via ESPN · as of ${new Date(d.as_of).toLocaleString()}`;
    } catch (e) { /* keep the baked page (empty-state stays) */ }
  };
  load();
  // Live tail: re-poll while the match is unfinished (mirrors the blow-by-blow/watch-along tick
  // above) — match stats are a live dataset (project_golazo26_live_hydration doctrine), so a
  // one-shot fetch would go stale the moment the match kicks off. Gated to the tournament window.
  const T0b = Date.parse('2026-06-11T00:00:00Z'), T1b = Date.parse('2026-07-20T12:00:00Z');
  const finishedB = () => !!document.querySelector(`[data-match="${n}"] .pill.ft`);
  if (Date.now() >= T0b && Date.now() <= T1b && !finishedB()) {
    const iv = setInterval(() => {
      if (Date.now() > T1b) { clearInterval(iv); return; }
      if (finishedB()) { load(); clearInterval(iv); return; } // one last load at FT for the final boxscore
      load();
    }, 45000 + Math.random() * 15000);
  }
  window.addEventListener('pageshow', (e) => { if (e.persisted) load(); });
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') load(); });
}

// Feed sync (the maintainer 0606): scroll the blow-by-blow (.cmt-list) and the AI Watch-Along (.wa-list)
// TOGETHER in match time. Both are newest-first scroll boxes; each cmt row carries data-seq, each wa row
// data-src-seq (the blow-by-blow seq that AI line reacts to). SYNC ON: scrolling one aligns the other to
// the same match-moment — and because the Watch-Along is SPARSE (keyed to goals/cards) it SNAPS to the AI
// line for the nearest key event you've reached and holds. Loop-guarded (a syncing flag + rAF). Persisted.
// OFF = independent scroll (no regression to the certified match-page IA). Reduced-motion → instant jump.
// Client-only; keyboard-accessible. Both feeds must exist (a scheduled/settled page may have neither).
(function () {
  const cmt = document.querySelector('[data-commentary] .cmt-list');
  const wa = document.querySelector('[data-watchalong] .wa-list');
  const cmtSec = document.querySelector('[data-commentary]');
  const waSec = document.querySelector('[data-watchalong]');
  if (!cmt || !wa || !cmtSec || !waSec) return;
  const KEY = 'g26-feed-sync';
  const instant = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
  let on = false, syncing = false, raf = 0, offTimer = 0;

  // Toggle by the blow-by-blow header — one control links both feeds. Keyboard-native <button>, labeled.
  const btn = document.createElement('button');
  btn.type = 'button'; btn.className = 'feed-sync-btn'; btn.setAttribute('aria-pressed', 'false');
  btn.hidden = true; // revealed only once BOTH feeds have content (they hydrate async; a settled/data-less match keeps it hidden)
  btn.innerHTML = '<i class="ti ti-arrows-vertical" aria-hidden="true"></i> Sync with AI Watch-Along';
  (cmtSec.querySelector('h2') || cmtSec).insertAdjacentElement('afterend', btn);

  // Topmost VISIBLE row's seq (rows are newest-first; the first whose bottom sits below the box top).
  const topSeq = (list, attr) => {
    const top = list.getBoundingClientRect().top;
    for (const li of list.children) {
      if (li.getBoundingClientRect().bottom > top + 2) { const v = parseInt(li.getAttribute(attr), 10); return isNaN(v) ? null : v; }
    }
    return null;
  };
  // Align dst so its first row with seq <= target (the largest, since newest-first) sits at the box top.
  const alignTo = (list, attr, seq) => {
    let target = null;
    for (const li of list.children) { const v = parseInt(li.getAttribute(attr), 10); if (!isNaN(v) && v <= seq) { target = li; break; } }
    if (!target) return;
    syncing = true;
    list.scrollBy({ top: target.getBoundingClientRect().top - list.getBoundingClientRect().top, behavior: instant ? 'auto' : 'smooth' });
    clearTimeout(offTimer); offTimer = setTimeout(() => { syncing = false; }, instant ? 20 : 380); // release the loop-guard after the scroll settles
  };
  const link = (src, srcAttr, dst, dstAttr) => {
    if (!on || syncing) return; // loop-guard: ignore the programmatic scroll we just caused
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => { const s = topSeq(src, srcAttr); if (s != null) alignTo(dst, dstAttr, s); });
  };
  cmt.addEventListener('scroll', () => link(cmt, 'data-seq', wa, 'data-src-seq'), { passive: true });
  wa.addEventListener('scroll', () => link(wa, 'data-src-seq', cmt, 'data-seq'), { passive: true });

  const setOn = (v) => {
    on = v; btn.classList.toggle('on', v); btn.setAttribute('aria-pressed', v ? 'true' : 'false');
    try { localStorage.setItem(KEY, v ? '1' : '0'); } catch (e) {}
    if (v) { const s = topSeq(cmt, 'data-seq'); if (s != null) alignTo(wa, 'data-src-seq', s); } // align immediately on enable
  };
  btn.addEventListener('click', () => setOn(!on));

  // Reveal the toggle only when BOTH feeds actually have ROWS (.cmt/.wa — not just any child nodes)
  // in VISIBLE sections (reveal-leak fix: the button teased a Watch-Along that wasn't
  // there on m86). And keep guarding for the page's life: re-HIDE if the feed empties or its section
  // hides, and late-REVEAL when a drain/sweep backfills rows after load. Hiding disables sync without
  // clobbering the persisted preference, so a returning feed restores the user's choice.
  const feedsReady = () =>
    !cmtSec.hidden && !waSec.hidden && !!cmt.querySelector('.cmt') && !!wa.querySelector('.wa');
  const reveal = () => {
    if (!feedsReady()) return false;
    btn.hidden = false;
    try { if (localStorage.getItem(KEY) === '1' && !on) setOn(true); } catch (e) {}
    return true;
  };
  if (!reveal()) {
    const iv = setInterval(() => { if (reveal()) clearInterval(iv); }, 1000);
    setTimeout(() => clearInterval(iv), 120000);
  }
  setInterval(() => {
    if (btn.hidden) { reveal(); return; }             // late data (sweep backfill) → reveal
    if (!feedsReady()) {                               // feed gone/hidden → never tease a dead control
      btn.hidden = true;
      on = false; btn.classList.remove('on'); btn.setAttribute('aria-pressed', 'false'); // disable w/o persisting
    }
  }, 8000);
})();
// The Story timeline + key-moments strip (Phase 2, items 2.4b/2.5b — closes the 1.7 deferral): both
// LIVE-UPDATE during a match from the STRUCTURED match-events feed at /api/v1/match-events?n=N — the
// same events_json the bake renders, so the certified timelineHTML/keyMomentsHTML produce byte-identical
// markup with NO rebuild. LIVE DATASET: re-polls in lockstep with the commentary/stats tick (never a
// one-shot — project_golazo26_live_hydration), as_of(updated_at)-idempotent, and catches up on bfcache
// restore / tab refocus. GRACEFUL EMPTY: events:[] / {error:not-found} / non-200 all keep the baked
// (or hidden) view — never a broken row. Every field is HTML-escaped inside the renderers before it
// reaches innerHTML (ESPN incident copy is third-party). Fails safe: any error leaves the baked page.
const story = document.querySelector('[data-story]');
const kmo = document.querySelector('[data-kmoments]');
if (story || kmo) {
  const host = story || kmo;
  const n = host.getAttribute('data-story') || host.getAttribute('data-kmoments');
  const API7 = self.__G26_API__ || 'https://golazo26-data.onwike.workers.dev';
  const codes = kmo ? { home: kmo.getAttribute('data-home-code') || '', away: kmo.getAttribute('data-away-code') || '' } : null;
  let lastAsof = null;
  const load = async () => {
    try {
      const r = await fetch(`${API7}/api/v1/match-events?n=${encodeURIComponent(n)}`, { cache: 'no-cache' });
      if (!r.ok) return;
      const d = await r.json();
      if (!d || !Array.isArray(d.events) || !d.events.length) return; // keep the baked/hidden view
      if (d.as_of && d.as_of === lastAsof) return; // no new events since last paint
      lastAsof = d.as_of || lastAsof;
      if (story) {
        const tl = timelineHTML(d.events);
        if (tl) { story.querySelector('.mtl-rows').innerHTML = tl; story.hidden = false; }
      }
      if (kmo) {
        const strip = keyMomentsHTML(d.events, codes);
        if (strip) { kmo.innerHTML = strip; kmo.hidden = false; }
      }
    } catch (e) { /* keep the baked page (baked or hidden view stays) */ }
  };
  load();
  // Live tail: re-poll while the match is unfinished (mirrors the commentary/watch/stats tick above),
  // gated to the tournament window so settled / out-of-window pages never poll.
  const T0c = Date.parse('2026-06-11T00:00:00Z'), T1c = Date.parse('2026-07-20T12:00:00Z');
  const finishedC = () => !!document.querySelector(`[data-match="${n}"] .pill.ft`);
  if (Date.now() >= T0c && Date.now() <= T1c && !finishedC()) {
    const iv = setInterval(() => {
      if (Date.now() > T1c) { clearInterval(iv); return; }
      if (finishedC()) { load(); clearInterval(iv); return; } // one last load at FT for the closing events
      load();
    }, 45000 + Math.random() * 15000);
  }
  window.addEventListener('pageshow', (e) => { if (e.persisted) load(); });
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') load(); });
}
